CREATE OR REPLACE FUNCTION public.attach_fixed_service_consent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare consent uuid;
begin
  if tg_op='UPDATE' and (exists(select 1 from public.fixed_purchase_service_contracts_v1 where purchase_id=old.id) or
      old.status not in ('pending','processing','failed') or old.access_granted or old.earnings_credited_at is not null) then
    if new.fixed_service_consent_id is distinct from old.fixed_service_consent_id then
      raise exception 'Existing purchase service promise is immutable'; end if;
    return new;
  end if;
  select c.id into consent from public.product_checkout_attempts attempt
    join public.product_purchase_consents_v1 c on c.id=attempt.purchase_consent_id
    where attempt.stripe_checkout_session_id=new.session_id and attempt.buyer_id=new.buyer_id and
      attempt.creator_id=new.creator_id and attempt.product_id=new.product_id and attempt.post_id is not distinct from new.post_id and
      c.terms->>'serviceVersion'='fixed-service-months-v1';
  if new.fixed_service_consent_id is not null and new.fixed_service_consent_id is distinct from consent and
    (tg_op='INSERT' or new.session_id is not distinct from old.session_id) then
    raise exception 'Purchase service consent binding differs'; end if;
  new.fixed_service_consent_id:=consent;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.bind_purchase_delivery_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare s public.checkout_delivery_snapshots%rowtype; old_order uuid; delivery_order uuid; p public.products%rowtype;
begin
 delivery_order:=coalesce(new.order_id,new.id);
 select order_id into old_order from public.purchase_deliveries where purchase_id=new.id;
 if found and old_order is distinct from delivery_order then raise exception 'Purchase delivery cannot be replaced'; end if;
 -- Monthly and guarded installment reservations seed their purchase before
 -- opening Checkout. They keep their original financial identities and fields.
 if tg_op='INSERT' and new.order_id is null then
  select * into p from public.products where id=new.product_id;
  if p.delivery_revision is not null then
   if p.creator_id is distinct from new.creator_id then raise exception 'Reserved product owner differs'; end if;
   perform public.prepare_checkout_delivery_v1(delivery_order,new.buyer_id,p.id,p.delivery_revision,p.price_cents);
  end if;
 end if;
 select * into s from public.checkout_delivery_snapshots where order_id=delivery_order;
 if not found then return new; end if;
 if new.buyer_id is distinct from s.buyer_id or new.creator_id is distinct from s.creator_id or
  new.product_id is distinct from s.product_id or (old_order is null and new.order_id is not null and new.amount_cents is distinct from s.amount_cents) or
  lower(new.currency) is distinct from s.currency then raise exception 'Purchase delivery ownership or price differs'; end if;
 insert into public.purchase_deliveries(purchase_id,order_id) values(new.id,s.order_id) on conflict(purchase_id) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_monthly_initial_purchase_close_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.monthly_mentorship_agreements_v1%rowtype;
begin
  if new.kind is distinct from 'monthly_mentorship_v1' and new.monthly_mentorship_id is null then return new; end if;
  select * into a from public.monthly_mentorship_agreements_v1 where id=new.monthly_mentorship_id and purchase_id=new.id;
  if not found or new.kind is distinct from 'monthly_mentorship_v1' then raise exception 'Initial close-out purchase identity differs'; end if;
  if (new.status='canceled' and (a.initial_abandoned_at is null or a.covered_months<>0 or a.initial_abandon_proof is null)) or
    (a.initial_abandoned_at is not null and new.status is distinct from 'canceled') then
    raise exception 'Monthly canceled purchase requires proven unpaid close-out'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_monthly_mentorship_purchase_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.monthly_mentorship_agreements_v1%rowtype;
begin
  if tg_op='UPDATE' and old.monthly_mentorship_id is not null and new.monthly_mentorship_id is distinct from old.monthly_mentorship_id then
    raise exception 'Monthly purchase identity cannot be replaced'; end if;
  if new.monthly_mentorship_id is null then
    if exists(select 1 from public.products where id=new.product_id and membership_terms is not null) then
      raise exception 'Monthly offer requires its owned membership purchase'; end if;
    return new;
  end if;
  select * into a from public.monthly_mentorship_agreements_v1 where id=new.monthly_mentorship_id;
  if not found or a.purchase_id is distinct from new.id or a.buyer_id is distinct from new.buyer_id or
    a.creator_id is distinct from new.creator_id or a.product_id is distinct from new.product_id or a.post_id is distinct from new.post_id or
    new.kind is distinct from 'monthly_mentorship_v1' or new.access_granted is distinct from false or
    new.earnings_credited_at is not null or coalesce(new.paid_count,0)<>0 or new.target_months is not null or
    new.subscription_id is distinct from a.stripe_subscription_id then
    raise exception 'Monthly service cannot use legacy ownership, entitlement, or installment credit'; end if;
  return new;
end;
$function$

